def main():
    # Load existing questions to avoid duplicates
    existing = set()
    if os.path.exists(CSV_PATH):
        with open(CSV_PATH, newline="", encoding="utf-8") as f:
            for row in csv.DictReader(f):
                existing.add(row["input_text"].strip())

    new_rows = [(q, a) for q, a in ENTRIES if q.strip() not in existing]

    with open(CSV_PATH, "a", newline="", encoding="utf-8") as f:
        writer = csv.writer(f, quoting=csv.QUOTE_MINIMAL)
        for q, a in new_rows:
            writer.writerow([q, a])

    print(f"Authored entries: {len(ENTRIES)}")
    print(f"Skipped as duplicates: {len(ENTRIES) - len(new_rows)}")
    print(f"Appended: {len(new_rows)}")


if __name__ == "__main__":
    main()
